"Centre de localisation":"Centre ya localisation",
"Autoriser la localisation":"Pesa nzela ya localisation",
"Cette autorisation permet à l'application d'utiliser la position GPS de votre appareil pour afficher votre position, activer le partage de localisation et les fonctions de sécurité que vous choisissez. Rien n'est partagé sans votre action.":"Permission oyo ezali kopesa application nzela ya kosalela position GPS ya appareil na yo mpo na komonisa esika ozali, kopelisa kokabola localisation mpe ba fonctions ya sécurité oyo opona. Eloko moko te ekabolami soki osali eloko te.",
"Localisation désactivée":"Localisation ezali pelisami te",
"Recherche de la position…":"Ezali koluka esika ozali…",
"Permission refusée":"Permission eboyami",
"Position indisponible":"Position ezwami te",
"Délai dépassé":"Ntango esili",
"Navigateur incompatible":"Navigateur ekokani te",
"Connexion non sécurisée":"Connexion ezali na sécurité te",
"La localisation est refusée ou bloquée pour cette application. Autorise-la dans les réglages du navigateur (cadenas ▸ Autorisations ▸ Position), puis réessaie. L'application reste utilisable sans.":"Localisation eboyami to ekangami mpo na application oyo. Pesa nzela na ba réglages ya navigateur (cadenas ▸ Ba autorisations ▸ Position), sima meka lisusu. Application ekoki kosalelama ata soki ezali yango te.",
"Ton appareil n'arrive pas à déterminer sa position. Vérifie que le GPS est activé et que tu as du réseau, puis réessaie.":"Appareil na yo ezali na makoki te ya koluka esika ezali. Tala soki GPS epelisami mpe soki ozali na réseau, sima meka lisusu.",
"La position met trop de temps à arriver. Essaie à l'extérieur ou près d'une fenêtre.":"Position ezali kokoma na tango milai. Meka libanda to pene ya fenêtre.",
"Ce navigateur ne gère pas la géolocalisation. Essaie Chrome, Safari ou Firefox à jour.":"Navigateur oyo ezali kosalela géolocalisation te. Meka Chrome, Safari to Firefox ya sika.",
"La géolocalisation exige une connexion sécurisée (HTTPS).":"Géolocalisation esengi connexion na sécurité (HTTPS).",
"Une erreur est survenue. Réessaie.":"Libunga ebimi. Meka lisusu.",
"Action refusée : les règles Firestore du Centre de localisation ne sont pas encore publiées (ou pas à jour). Va dans la section « Vérifier ma configuration » (onglet Confidentialité).":"Likambo eboyami : ba règles Firestore ya Centre ya localisation epublié naino te (to ezali à jour te). Kende na section « Vérifier ma configuration » (onglet Confidentialité).",
"Index Firestore manquant : voir la console du navigateur.":"Index ya Firestore ezali te : tala console ya navigateur.",
