"MODE SOS ACTIF depuis {ago}":"MODE SOS EZALI KOSALA longwa {ago}",
"DÉSACTIVER LE SOS":"KANGA SOS",
"SOS activé.":"SOS epelisami.",
"SOS désactivé.":"SOS ekangami.",
"{name} a activé le mode urgence. Ouvre le Centre de localisation pour voir sa position.":"{name} apelisi mode ya urgence. Fungola Centre ya localisation mpo na komona position na ye.",
