"Position introuvable pour l'instant : le SOS est actif et se mettra à jour dès qu'une position arrive.":"Position ezwami naino te : SOS ezali kosala mpe ekobongisama mbala moko position ekoya.",
"en attente":"ezali kozela",
"Invitations reçues":"Ba invitations ezwami",
