"Choisis un mot de passe long et unique et ne le partage jamais : l’équipe ne te le demandera jamais.":"Pona mot de passe molai mpe moko kaka, mpe kabola yango ata mbala moko te : équipe ekosenga yango na yo ata mbala moko te.",
"Les messages de tes visiteurs sont stockés sur des serveurs sécurisés ; les formulaires sont protégés contre le spam et les robots.":"Ba messages ya ba visiteurs na yo ebombami na ba serveurs ya libateli ; ba formulaires ebatelami na spam mpe na ba robots.",
"Ton site est servi en HTTPS : les données échangées sont chiffrées.":"Site na yo ezali na HTTPS : ba données oyo ezali kotambola ezali chiffrées.",
"En cas de doute, change ton mot de passe et écris-nous dans l’onglet Aide.":"Soki ozali na ntembe, bongola mot de passe na yo mpe koma na biso na onglet Lisungi.",
